{
  "summary": "The diff adds context-specific XInclude error handling and changes memory-error reporting. The packet supports candidate harness gaps, but the Autoconf default and the document node's doc pointer are decisive missing facts, so maintenance necessity remains unknown.",
  "coverage_complete": false,
  "coverage_evidence": [],
  "claims": [
    {
      "claim_id": "context_error_callback",
      "necessary": "unknown",
      "necessity_reason": "The new context-specific callback cannot be selected by the old harness. Whether XInclude is enabled by this build recipe is not established by the supplied Autoconf evidence.",
      "before": {
        "requirement": "Context-specific XInclude error callback delivery was not available through the XInclude context.",
        "applicability": "not_applicable",
        "harness_status": "not_applicable",
        "reason": "The old XInclude error path passed no context callback, and the complete old xinclude.c has no setter definition.",
        "source_evidence": [
          {
            "unit_id": "u-05c4e8678f716329c748",
            "start_line": 152,
            "end_line": 164,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-9161b390ecbe6d6bd10e",
            "start_line": 2393,
            "end_line": 2393,
            "role": "dependency",
            "dependency_reason": "The supplied preimage verification establishes absence of the setter definition in xinclude.c."
          }
        ]
      },
      "after": {
        "requirement": "A configured XInclude context delivers its errors to its structured callback with the supplied user data.",
        "applicability": "unknown",
        "harness_status": "unknown",
        "reason": "The source adds the setter and forwards XInclude errors through it, while the old harness never calls the setter. The recipe's Autoconf XInclude default is missing.",
        "source_evidence": [
          {
            "unit_id": "u-3cc3b8db38e2c69a4911",
            "start_line": 2378,
            "end_line": 2385,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-d77c6564c4f9d47d591a",
            "start_line": 155,
            "end_line": 161,
            "role": "dependency",
            "dependency_reason": "The configured callback and user data are passed to the XInclude error producer."
          }
        ]
      },
      "same_blocker": "not_applicable",
      "harness_evidence": [
        {
          "unit_id": "u-19cd550c9faddbff1f06",
          "start_line": 15,
          "end_line": 24,
          "role": "dependency",
          "dependency_reason": "Initialization installs a generic error handler, not a context-specific structured handler."
        },
        {
          "unit_id": "u-19cd550c9faddbff1f06",
          "start_line": 50,
          "end_line": 69,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-76ce59b6fbe650f18145",
          "start_line": 26,
          "end_line": 44,
          "role": "dependency",
          "dependency_reason": "The recipe configures and links the xinclude target, but does not state the Autoconf feature default."
        }
      ],
      "comparison_reason": "The setter and callback forwarding are new. The old harness has no call that supplies a context callback; final applicability depends on the missing build default.",
      "missing_information": [
        "The XInclude feature default used by ./autogen.sh in configure.ac."
      ],
      "change_ids": ["g0001", "g0002", "g0004", "g0045"]
    },
    {
      "claim_id": "xinclude_memory_error_assertion",
      "necessary": "unknown",
      "necessity_reason": "On a reached XInclude allocation failure, the changed helper no longer sets ctxt->errNo, which the existing harness check reads. Whether the harness's document-node call reaches that helper depends on an unsupplied document creation fact.",
      "before": {
        "requirement": "An XInclude allocation failure records XML_ERR_NO_MEMORY in the XInclude context for the existing check.",
        "applicability": "required",
        "harness_status": "unknown",
        "reason": "The old helper sets errNo, but it is unresolved whether the old harness reaches XInclude processing with its document-node argument.",
        "source_evidence": [
          {
            "unit_id": "u-fd0ee43254fd372c2f9c",
            "start_line": 130,
            "end_line": 141,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-f19e0f43506717e2d7c5",
            "start_line": 2568,
            "end_line": 2578,
            "role": "dependency",
            "dependency_reason": "The process call rejects a node whose doc field is NULL."
          }
        ]
      },
      "after": {
        "requirement": "An XInclude allocation failure remains recognizable as XML_ERR_NO_MEMORY by the existing XInclude-context check.",
        "applicability": "required",
        "harness_status": "unknown",
        "reason": "The new helper updates a global error but does not set ctxt->errNo. The document-node guard may prevent the old harness from reaching the failure path.",
        "source_evidence": [
          {
            "unit_id": "u-37bf4d3e35073e6d1dcb",
            "start_line": 133,
            "end_line": 138,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-49818a698983bc9badbc",
            "start_line": 584,
            "end_line": 609,
            "role": "dependency",
            "dependency_reason": "The delegated memory-error routine updates global and optional error structures; this call passes NULL for the optional error structure."
          },
          {
            "unit_id": "u-b366f63bd83e89f93f88",
            "start_line": 2564,
            "end_line": 2574,
            "role": "dependency",
            "dependency_reason": "The process call retains the node->doc guard."
          }
        ]
      },
      "same_blocker": "unknown",
      "harness_evidence": [
        {
          "unit_id": "u-19cd550c9faddbff1f06",
          "start_line": 50,
          "end_line": 69,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-ab97f2d7a2b55b1a45d3",
          "start_line": 121,
          "end_line": 128,
          "role": "dependency",
          "dependency_reason": "A mismatch between injected allocation failure and the expected error indication aborts the target."
        },
        {
          "unit_id": "u-3bf543b1ba71657b7e3e",
          "start_line": 104,
          "end_line": 109,
          "role": "dependency",
          "dependency_reason": "The harness resets the allocation-failure counter before processing."
        }
      ],
      "comparison_reason": "The context error field was updated before and is not updated by the new memory-error helper. Reachability through the fixed old call remains unresolved.",
      "missing_information": [
        "The value of the doc field in a document returned by xmlCtxtReadMemory, including its construction path through xmlDoRead and xmlSAX2StartDocument."
      ],
      "change_ids": ["g0003", "g0044"]
    },
    {
      "claim_id": "document_node_process_reachability",
      "necessary": "unknown",
      "necessity_reason": "The old harness passes the document itself to xmlXIncludeProcessNode on both sides. The source rejects that argument if its doc field is NULL; the packet does not establish that field's value.",
      "before": {
        "requirement": "The DOM XInclude operation must reach processing for a valid parsed document containing an include.",
        "applicability": "required",
        "harness_status": "unknown",
        "reason": "The process function requires node->doc, but the returned document's corresponding field is not established.",
        "source_evidence": [
          {
            "unit_id": "u-f19e0f43506717e2d7c5",
            "start_line": 2568,
            "end_line": 2578,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-94e35ccb616866d9e6da",
            "start_line": 14843,
            "end_line": 14873,
            "role": "dependency",
            "dependency_reason": "The parser entry returns the document passed by the harness, but delegates its creation to xmlDoRead."
          }
        ]
      },
      "after": {
        "requirement": "The same DOM XInclude operation must reach processing for a valid parsed document containing an include.",
        "applicability": "required",
        "harness_status": "unknown",
        "reason": "The unchanged guard still requires node->doc; the document creation path remains missing.",
        "source_evidence": [
          {
            "unit_id": "u-b366f63bd83e89f93f88",
            "start_line": 2564,
            "end_line": 2575,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-3ddcae0f5666b6760727",
            "start_line": 14843,
            "end_line": 14873,
            "role": "dependency",
            "dependency_reason": "The parser entry delegates document creation to xmlDoRead on the after side as well."
          }
        ]
      },
      "same_blocker": "unknown",
      "harness_evidence": [
        {
          "unit_id": "u-19cd550c9faddbff1f06",
          "start_line": 56,
          "end_line": 67,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The same document-node argument and the same source guard exist before and after. A shared blocker can be established only after the document field is known.",
      "missing_information": [
        "The doc field of the document returned by xmlCtxtReadMemory.",
        "Whether another old-harness call reaches equivalent nonstreaming DOM XInclude processing if the document-node call is rejected."
      ],
      "change_ids": ["g0044"]
    }
  ],
  "missing_information": [
    "Read configure.ac to establish the XInclude and reader defaults used by the supplied Autoconf recipe.",
    "Read xmlDoRead, xmlSAX2StartDocument, and xmlNewDoc to establish the returned document node's doc field."
  ],
  "requested_symbols": ["xmlDoRead", "xmlSAX2StartDocument", "xmlNewDoc"],
  "requested_paths": ["configure.ac", "parser.c", "SAX2.c", "tree.c"]
}
